parameters.jsCode:
// Validate the incoming request and split every uploaded PDF into its
// own item so each resume is processed independently.
const item = $input.first();
const body = (item.json && item.json.body) ? item.json.body : {};
const binary = item.binary || {};

const jd = String(body.job_description || body.jd || '').trim();
const recruiterName = String(body.recruiter_name || '').trim();
const recruiterEmail = String(body.recruiter_email || '').trim();

const fileKeys = Object.keys(binary);

// --- Validation ---
const errors = [];
if (!jd) errors.push('job_description is required');
if (fileKeys.length === 0) errors.push('at least one PDF resume is required');
if (errors.length > 0) {
  return [{ json: { valid: false, error: errors.join('; ') } }];
}

// --- Split: one item per resume, binary normalised to 'data' ---
const out = [];
let idx = 0;
for (const key of fileKeys) {
  const b = binary[key];
  out.push({
    json: {
      valid: true,
      jd_text: jd,
      recruiter_name: recruiterName,
      recruiter_email: recruiterEmail,
      resume_index: idx,
      file_name: (b && b.fileName) ? b.fileName : key,
    },
    binary: { data: b },
  });
  idx++;
}
return out;

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "candidate_name": { "type": "string", "description": "Candidate full name from the resume." },
    "email": { "type": "string", "description": "Candidate email, or empty string if none." },
    "score": { "type": "number", "description": "Match score 0-100 vs the job description." },
    "tier": { "type": "string", "enum": ["Strong Fit", "Possible Fit", "Not Fit"], "description": "Classification vs the JD." },
    "matched_skills": { "type": "array", "items": { "type": "string" }, "description": "JD requirements the candidate meets." },
    "missing_skills": { "type": "array", "items": { "type": "string" }, "description": "JD requirements the candidate lacks." },
    "reasoning": { "type": "string", "description": "Detailed rationale of what matched or is missing." },
    "recommendation": { "type": "string", "description": "Short next-step recommendation for the recruiter." }
  },
  "required": ["candidate_name", "email", "score", "tier", "matched_skills", "missing_skills", "reasoning", "recommendation"]
}

parameters.jsCode:
// Normalise every AI result, derive status + recommendation, and flag
// duplicate candidates (same email seen earlier in this batch).
const items = $input.all();
const meta = $('Validate & Split Resumes').all();
const seen = {};
const results = [];
for (let i = 0; i < items.length; i++) {
  const o = items[i].json.output || {};
  const m = (meta[i] && meta[i].json) ? meta[i].json : {};
  const email = String(o.email || '').trim().toLowerCase();
  const tier = String(o.tier || 'Not Fit');

  let status = 'Rejected';
  if (tier === 'Strong Fit') status = 'Invited';
  else if (tier === 'Possible Fit') status = 'Review Required';

  const isDup = email !== '' && seen[email] === true;
  if (email !== '') seen[email] = true;

  const scoreNum = typeof o.score === 'number' ? o.score : (Number(o.score) || 0);

  results.push({ json: {
    candidate_name: o.candidate_name || 'Unknown',
    email: o.email || '',
    score: scoreNum,
    tier: tier,
    matched_skills: Array.isArray(o.matched_skills) ? o.matched_skills : [],
    missing_skills: Array.isArray(o.missing_skills) ? o.missing_skills : [],
    reasoning: o.reasoning || '',
    recommendation: o.recommendation || '',
    status: isDup ? 'Duplicate' : status,
    is_duplicate: isDup,
    is_strong_fit: tier === 'Strong Fit' && !isDup,
    file_name: m.file_name || '',
    recruiter_name: m.recruiter_name || '',
    recruiter_email: m.recruiter_email || '',
    screened_at: new Date().toISOString(),
  } });
}
return results;

// Build a single clean JSON payload for the Flask website.
const rows = $('Build Result & Dedup').all().map(i => i.json);
const candidates = rows.map(r => ({
  candidate_name: r.candidate_name,
  email: r.email,
  score: r.score,
  tier: r.tier,
  matched_skills: r.matched_skills,
  missing_skills: r.missing_skills,
  reasoning: r.reasoning,
  recommendation: r.recommendation,
  status: r.status,
  invited: r.is_strong_fit,
  is_duplicate: r.is_duplicate,
}));
const summary = {
  total: candidates.length,
  strong_fit: candidates.filter(c => c.tier === 'Strong Fit').length,
  possible_fit: candidates.filter(c => c.tier === 'Possible Fit').length,
  not_fit: candidates.filter(c => c.tier === 'Not Fit').length,
  duplicates: candidates.filter(c => c.is_duplicate).length,
};
return [{ json: { status: 'success', summary, candidates } }];

